// === Tab: Fragment ===
class Fragment
{
	constructor(x, y, width, height) {
		this.originX = x;
		this.originY = y;
		this.x = x;
		this.y = y;
		this.w = width;
		this.h = height;
  }

  setImage(img){
    this.img = img.get(this.x, this.y, this.w, this.h);
  }

  update(){
		var diffX = width/2 - this.originX;
		var diffY = height/2 - this.originY;
		var angle = atan2(diffY, diffX);
		var time = millis()/3000;
		this.x = this.originX + cos(time + angle) * 50;
		this.y = this.originY + sin(time + angle) * 50;
  }

  draw(){
    image(this.img, this.x, this.y);
  }
}

